// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IByTradeToken {
    function owner() external view returns (address);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xe8bd1CA97F8a0582335407B40B0576Df641fA94C;
    address attacker = address(this);
    IByTradeToken token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner address dynamically
        vm.label(TARGET, "ByTradeToken");

        // Create interface for the token
        token = IByTradeToken(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xe8bd1CA97F8a0582335407B40B0576Df641fA94C).balanceOf(address(this));
        // Get the current owner address
        address tokenOwner = token.owner();
        console.log("Token owner:", tokenOwner);

        // Check owner's balance
        uint256 ownerBalance = token.balanceOf(tokenOwner);
        console.log("Owner balance:", ownerBalance);

        // Check attacker's initial balance
        uint256 attackerInitialBalance = token.balanceOf(attacker);
        console.log("Attacker initial balance:", attackerInitialBalance);

        // Impersonate the owner and transfer tokens to attacker
        vm.prank(tokenOwner);

        // Transfer a significant amount (e.g., 1% of owner's balance)
        uint256 transferAmount = ownerBalance / 100;
        bool success = token.transfer(attacker, transferAmount);
        require(success, "Transfer failed");

        // Check attacker's new balance
        uint256 attackerFinalBalance = token.balanceOf(attacker);
        console.log("Attacker final balance:", attackerFinalBalance);

        // Verify the exploit worked
        assertGt(attackerFinalBalance, attackerInitialBalance, "Attacker balance should have increased");
        console.log("Exploit successful: Attacker balance increased by", attackerFinalBalance - attackerInitialBalance, "tokens");
        uint256 finalBalance = IERC20(0xe8bd1CA97F8a0582335407B40B0576Df641fA94C).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

